package main

import (
	"fmt"         // https://pkg.go.dev/fmt — Package fmt implements formatted I/O with functions analogous to C's printf and scanf.
	"runtime/cgo" // https://pkg.go.dev/runtime/cgo — Package cgo contains runtime support for code generated by the cgo tool.
)

// runtime/cgo is normally an implementation detail of `import "C"`, but
// it also exposes cgo.Handle — a uintptr you can hand to C and then use
// to look up the original Go value on the way back. Here we skip the C
// side and just do the round-trip in Go.
func runCGO() {
	original := map[string]int{"answer": 42}

	h := cgo.NewHandle(original)
	defer h.Delete()

	// Pretend h has taken a trip through a C API and come back.
	got := h.Value().(map[string]int)
	fmt.Printf("handle: %d\n", uintptr(h))
	fmt.Printf("value:  %v\n", got)
	got["answer"] = 99
	fmt.Printf("mutation visible on original: %v\n", original["answer"] == 99)
}
